'use strict';
function dateInput(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function periodBounds(key=period,now=Date.now()){
 const end=new Date(now),start=new Date(now);start.setHours(0,0,0,0);end.setHours(0,0,0,0);end.setDate(end.getDate()+1);
 if(key==='all')return {start:0,end:end.getTime(),previousStart:0,previousEnd:0};
 if(key==='week'){const weekday=(start.getDay()+6)%7;start.setDate(start.getDate()-weekday);const p=new Date(start);p.setDate(p.getDate()-7);const pe=new Date(p);pe.setTime(pe.getTime()+(now-start.getTime())+1);return {start:+start,end:now+1,previousStart:+p,previousEnd:+pe};}
 if(key==='month'){start.setDate(1);const p=new Date(start);p.setMonth(p.getMonth()-1);const pe=new Date(p);const last=new Date(start);last.setDate(0);pe.setDate(Math.min(new Date(now).getDate(),last.getDate()));pe.setHours(new Date(now).getHours(),new Date(now).getMinutes(),new Date(now).getSeconds(),new Date(now).getMilliseconds());return {start:+start,end:now+1,previousStart:+p,previousEnd:+pe+1};}
 const days=Number(key)||7;start.setDate(start.getDate()-days+1);const p=new Date(start);p.setDate(p.getDate()-days);return {start:+start,end:+end,previousStart:+p,previousEnd:+start};
}
function orderTime(o){return o.status==='completed'?Number(o.completed||o.created):o.status==='returned'?Number(o.returned||o.created):o.status==='rejected'?Number(o.rejected||o.created):Number(o.created);}
function inRange(value,range){return value>=range.start&&value<range.end;}
function scopedOrders(range=periodBounds(),branch=branchFilter){return state.orders.filter(o=>canBranch(state,o.branch)&&(branch==='all'||o.branch===branch)&&inRange(orderTime(o),range));}
function scopedCosts(range=periodBounds(),branch=branchFilter){const end=new Date(range.end);if(end.getHours()||end.getMinutes()||end.getSeconds()||end.getMilliseconds()){end.setHours(0,0,0,0);end.setDate(end.getDate()+1);}return expenses.filter(e=>canBranch(state,e.branch)&&(branch==='all'||e.branch===branch)&&inRange(e.date,{start:range.start,end:+end}));}
function financialSummary(list,costs){const done=list.filter(o=>o.status==='completed');let sales=0,fee=0,food=0,missing=0,estimated=0;for(const o of done){sales+=amount(o);fee+=Math.round(amount(o)*(Number.isFinite(o.commissionRate)?o.commissionRate:Number(state.profile.commission))/100);for(const i of o.items){const c=itemCost(state,i);food+=c.value*i.qty;if(c.source==='missing')missing+=i.qty;if(c.source==='estimate')estimated+=i.qty;}}
 const wages=costs.filter(e=>e.category==='wage').reduce((s,e)=>s+e.amount,0),other=costs.filter(e=>e.category!=='wage').reduce((s,e)=>s+e.amount,0);return {done,sales,fee,food,wages,other,cost:wages+other,net:sales-fee-food-wages-other,missing,estimated};}
function profitNote(s){return s.missing?`${s.missing} dona taom tannarxi kiritilmagan — foyda to‘liq emas.`:s.estimated?`${s.estimated} dona tarixiy taom uchun joriy tannarxdan taxmin olindi.`:'Tannarxlar buyurtmalarda qayd etilgan.';}
function delayed(o,now=Date.now()){const limit=(Number(o.prepTime)||Number(state.profile.prepTime)||20)*60000;if(o.status==='preparing')return now-(o.accepted||o.created)>limit;if(o.status==='new')return now-o.created>5*60000;return false;}
function wasLate(o){return o.readyAt&&o.accepted?o.readyAt-o.accepted>(Number(o.prepTime)||state.profile.prepTime||20)*60000:delayed(o);}
function branchMetrics(){return scopedBranches(state).filter(b=>branchFilter==='all'||b.id===branchFilter).map(b=>{const list=scopedOrders(periodBounds(),b.id),s=financialSummary(list,scopedCosts(periodBounds(),b.id));const ids=new Set(list.map(o=>String(o.id)));const reviews=(state.reviews||[]).filter(r=>(r.branch===b.id||ids.has(String(r.order)))&&inRange(new Date(r.date+'T00:00:00').getTime(),periodBounds()));const timed=list.filter(o=>o.accepted&&o.readyAt);return {b,list,s,late:list.filter(wasLate).length,timed:timed.length,rating:reviews.length?(reviews.reduce((sum,r)=>sum+r.rating,0)/reviews.length).toFixed(1):null,reviews:reviews.length};}).sort((a,b)=>b.s.sales-a.s.sales);}
function branchComparison(){const rows=branchMetrics();return `<section class="panel"><div class="panel-head"><h2>Filiallarni taqqoslash</h2><span class="tag">Savdo bo‘yicha</span></div><div class="table-wrap"><table><thead><tr><th>FILIAL</th><th>SAVDO</th><th>SOF FOYDA</th><th>BUYURTMA</th><th>KECHIKKAN</th><th>REYTING</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td><strong>${i+1}. ${esc(r.b.name)}</strong></td><td>${money(r.s.sales)}</td><td>${r.s.missing?'To‘liq emas':money(r.s.net)+(r.s.estimated?' ≈':'')}</td><td>${r.list.length}</td><td>${r.late} ta</td><td>${r.rating?'★ '+r.rating+' ('+r.reviews+')':'Ma’lumot yo‘q'}</td></tr>`).join('')}</tbody></table></div><p class="metric-note">Summalar so‘mda. Kechikish: yangi buyurtma 5 daqiqadan oshsa yoki tayyorlash muddati o‘tsa. Reyting faqat filialga bog‘langan sharhlardan olinadi.</p></section>`;}
function dishMetrics(list=selectedOrders()){const map=new Map(state.products.map(p=>[p.id,{id:p.id,name:p.name,product:p,qty:0,sales:0,food:0,fee:0,missing:0,estimated:0}]));for(const o of list.filter(o=>o.status==='completed')){let allocated=0;const orderFee=Math.round(amount(o)*(o.commissionRate??state.profile.commission)/100);o.items.forEach((i,index)=>{const p=i.productId?state.products.find(p=>p.id===i.productId):state.products.find(p=>p.name===i.name);const key=p?.id||'old:'+i.name;if(!map.has(key))map.set(key,{id:key,name:i.name,qty:0,sales:0,food:0,fee:0,missing:0,estimated:0});const row=map.get(key),c=itemCost(state,i),sales=i.price*i.qty;row.qty+=i.qty;row.sales+=sales;row.food+=c.value*i.qty;const fee=index===o.items.length-1?orderFee-allocated:Math.round(sales*(o.commissionRate??state.profile.commission)/100);allocated+=fee;row.fee+=fee;if(c.source==='missing')row.missing+=i.qty;if(c.source==='estimate')row.estimated+=i.qty;});}return [...map.values()].map(p=>({...p,profit:p.sales-p.food-p.fee}));}
function comparisonData(){const range=periodBounds();return {current:summary(),previous:financialSummary(scopedOrders({start:range.previousStart,end:range.previousEnd}),scopedCosts({start:range.previousStart,end:range.previousEnd}))};}
function changeLabel(current,previous){if(previous===0)return current===0?'O‘zgarish yo‘q':'Oldingi davrda savdo yo‘q';return `${current-previous>=0?'+':''}${((current-previous)/Math.abs(previous)*100).toFixed(1)}%`;}
function comparisons(){if(period==='all')return '';const {current:c,previous:p}=comparisonData();return `<section class="panel"><div class="panel-head"><h2>Davrlarni solishtirish</h2><span class="tag">${period==='1'?'Bugun / kecha':period==='week'?'Bu hafta / o‘tgan hafta':period==='month'?'Bu oy / o‘tgan oy':'Oldingi teng davr'}</span></div><p class="metric-note">Hafta va oy uchun oldingi davrning shu vaqtgacha bo‘lgan qismi olinadi. Bugun / kecha kunlari to‘liq kun chegaralari bilan hisoblanadi.</p><div class="comparison-grid">${[['Savdo',c.sales,p.sales],['Sof foyda',c.net,p.net],['Yakunlangan buyurtmalar',c.done.length,p.done.length]].map(([t,a,b])=>`<div><span>${t}</span><strong>${t==='Sof foyda'&&(c.missing||p.missing)?'To‘liq emas':changeLabel(a,b)}</strong><small>${money(a)} / ${money(b)} ${t.includes('buyurtma')?'ta':'so‘m'}</small></div>`).join('')}</div></section>`;}
function alertsData(){const live=state.orders.filter(o=>canBranch(state,o.branch)&&(branchFilter==='all'||o.branch===branchFilter)&&delayed(o));const selectedIds=new Set(selectedOrders().map(o=>String(o.id)));const bad=(state.reviews||[]).filter(r=>r.rating<=2&&(selectedIds.has(String(r.order))||(r.branch&&canBranch(state,r.branch)&&(branchFilter==='all'||r.branch===branchFilter)))&&inRange(new Date(r.date+'T00:00:00').getTime(),periodBounds()));const stopped=state.products.filter(p=>!p.available);const rows=[];if(live.length)rows.push({type:'danger',title:`${live.length} ta buyurtma kechikmoqda`,text:live.map(o=>'#'+o.id+' · '+branchName(o.branch)).slice(0,4).join(', '),view:'orders'});if(bad.length)rows.push({type:'danger',title:`${bad.length} ta past baho`,text:'1–2 yulduzli sharhlar. Sotuvchi panelida javob yozing.',view:'orders'});if(stopped.length)rows.push({type:'warning',title:`${stopped.length} ta taom sotuvdan olingan`,text:stopped.map(p=>p.name).join(', '),view:'dishes'});if(period!=='all'){const {current,previous}=comparisonData();if(previous.sales>0&&current.sales<previous.sales*.8)rows.push({type:'warning',title:'Savdo 20% dan ko‘proq pasaydi',text:`Oldingi teng davrga nisbatan ${changeLabel(current.sales,previous.sales)}.`,view:'finance'});}const s=summary();if(s.missing)rows.push({type:'warning',title:'Tannarxlar yetishmayapti',text:profitNote(s),view:'dishes'});return rows;}
function alertsPanel(){const rows=alertsData();return `<section class="panel"><div class="panel-head"><h2>Muhim ogohlantirishlar</h2><span class="tag ${rows.length?'warning':'success'}">${rows.length} ta</span></div>${rows.length?rows.map(a=>`<button type="button" class="owner-alert ${a.type}" data-action="nav" data-id="${a.view}"><span>${icon(a.type==='danger'?'clock':'bell')}</span><div><strong>${esc(a.title)}</strong><small>${esc(a.text)}</small></div><span>↗</span></button>`).join(''):'<div class="status-line">Muhim ogohlantirishlar yo‘q.</div>'}<p class="metric-note">Kechikishlar joriy holat bo‘yicha; past baholar va savdo tanlangan davr bo‘yicha. Menyu barcha filiallar uchun umumiy.</p></section>`;}
function dishesView(){const rows=dishMetrics(),sold=[...rows].sort((a,b)=>b.qty-a.qty),profitable=rows.filter(p=>p.qty&&!p.missing).sort((a,b)=>b.profit-a.profit),slow=rows.filter(p=>p.product).sort((a,b)=>a.qty-b.qty);return heading('Taomlar tahlili','Sotuv, tannarx va taomdan qoladigan hissa. Ish haqi va umumiy xarajatlar taomlar kesimiga taqsimlanmagan.')+filters()+`<div class="insight-cards">${[['Eng ko‘p sotilgan',sold[0]?.qty?sold[0].name:'Sotuv yo‘q',sold[0]?.qty?`${sold[0].qty} dona`: '—'],['Eng foydali taom',profitable[0]?.name||'Tannarx kiriting',profitable[0]?money(profitable[0].profit)+' so‘m':'—'],['Eng kam sotilgan',slow[0]?.name||'Menyu bo‘sh',slow[0]?`${slow[0].qty} dona`:'—']].map(([t,n,d])=>`<div class="panel"><span class="metric-note">${t}</span><h2>${esc(n)}</h2><strong>${d}</strong></div>`).join('')}</div><div class="panel table-wrap"><table><thead><tr><th>TAOM</th><th>TANNARX / DONA</th><th>SOTILGAN</th><th>SAVDO</th><th>FOYDA HISSASI</th><th>HOLAT</th><th></th></tr></thead><tbody>${sold.map(p=>`<tr><td><strong>${esc(p.name)}</strong></td><td>${Number.isFinite(p.product?.cost)?money(p.product.cost):'Kiritilmagan'}</td><td>${p.qty} dona</td><td>${money(p.sales)}</td><td>${p.missing?'To‘liq emas':money(p.profit)+(p.estimated?' ≈':'')}</td><td>${p.product?`<span class="tag ${p.product.available?'success':'warning'}">${p.product.available?'Sotuvda':'Stop-list'}</span>`:'Arxiv'}</td><td>${isOwner(state)&&p.product?button('Tannarx','product-cost',p.id,'small'):''}</td></tr>`).join('')}</tbody></table><p class="metric-note">≈ Tarixiy buyurtma uchun joriy tannarxdan olingan taxmin. Keyingi buyurtma yakunlanganda tannarx va komissiya qayd etiladi.</p></div>`;}
function dailyData(day=reportDate){const start=new Date(day+'T00:00:00'),end=new Date(start);end.setDate(end.getDate()+1);const list=scopedOrders({start:+start,end:+end}),s=financialSummary(list,scopedCosts({start:+start,end:+end}));return {list,s,top:dishMetrics(list).filter(p=>p.qty).sort((a,b)=>b.qty-a.qty).slice(0,3),rejected:list.filter(o=>o.status==='rejected').length};}
function dailyText(){const d=dailyData();return `Lazzat — kun yakuni: ${reportDate}\nFilial: ${branchFilter==='all'?'Barcha ruxsatli filiallar':branchName(branchFilter)}\nSavdo: ${money(d.s.sales)} so‘m\nTaom tannarxi: ${money(d.s.food)} so‘m\nKomissiya: ${money(d.s.fee)} so‘m\nIsh haqi: ${money(d.s.wages)} so‘m\nBoshqa xarajatlar: ${money(d.s.other)} so‘m\n${d.s.missing?'To‘liq bo‘lmagan foyda':'Sof foyda'}: ${money(d.s.net)} so‘m\n${profitNote(d.s)}\nYakunlangan: ${d.s.done.length}; rad etilgan: ${d.rejected}\nEng yaxshi taomlar: ${d.top.map(p=>p.name+' — '+p.qty+' dona').join(', ')||'Sotuv yo‘q'}\nDemo hisobot. Hali yakunlanmagan buyurtmalar savdoga kiritilmagan.`;}
function dailyView(){const d=dailyData();return heading('Kun yakuni hisoboti','Tanlangan kunning qisqa savdo va foyda hisoboti.',button('Hisobotni yuklash','download-daily','','primary'))+`<div class="filters"><input id="report-date" type="date" aria-label="Hisobot sanasi" value="${reportDate}" max="${dateInput()}"><select id="branch-filter" aria-label="Hisobot filiali"><option value="all">Barcha ruxsatli filiallar</option>${scopedBranches(state).map(b=>`<option value="${esc(b.id)}" ${branchFilter===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></div><div class="panel daily-report"><span class="tag">${reportDate}</span><h2>Biznesingizning kunlik natijasi</h2><div class="comparison-grid">${[['Savdo',d.s.sales],['Tannarx',d.s.food],['Komissiya',d.s.fee],['Ish haqi',d.s.wages],['Boshqa xarajatlar',d.s.other],['Sof foyda'+(d.s.missing?' (to‘liq emas)':d.s.estimated?' ≈':''),d.s.net]].map(([t,v])=>`<div><span>${t}</span><strong>${money(v)} <small>so‘m</small></strong></div>`).join('')}</div><div class="notice">${profitNote(d.s)}</div><p>Yakunlangan: <strong>${d.s.done.length}</strong> · Rad etilgan: <strong>${d.rejected}</strong></p><h2>Eng yaxshi taomlar</h2>${d.top.map((p,i)=>`<div class="summary-line"><span>${i+1}. ${esc(p.name)}</span><strong>${p.qty} dona · ${money(p.sales)} so‘m</strong></div>`).join('')||emptyOwner('Shu kuni yakunlangan savdo yo‘q.')}<p class="metric-note">Hisobot yakunlanmagan buyurtmalarni savdoga qo‘shmaydi. Xarajat va ish haqi jurnalga kiritilgan sana bo‘yicha olinadi.</p></div>`;}
function ownerActionAllowed(action,id){
 if(action==='close')return true;
 if(action==='nav')return ownerViews(state).includes(id);
 if(!ownerViews(state).length)return false;
 if(['branch','staff','toggle-staff','product-cost'].includes(action))return isOwner(state);
 if(action==='toggle-branch')return canBranch(state,id);
 if(action==='order')return state.orders.some(o=>o.id===id&&canBranch(state,o.branch));
 if(action==='delete-expense')return expenses.some(e=>e.id===id&&canBranch(state,e.branch));
 return ['expense','export','download-daily'].includes(action);
}
function ownerFormAllowed(form,values){
 if(['branch-form','staff-form','business-form','product-cost-form'].includes(form.id))return isOwner(state);
 if(!ownerViews(state).length)return false;
 if(form.id==='expense-form')return canBranch(state,values.get('branch'));
 if(form.id==='delete-expense-form')return expenses.some(e=>e.id===form.dataset.id&&canBranch(state,e.branch));
 return false;
}
function costModal(id){const p=state.products.find(p=>p.id===id);if(!p||!isOwner(state))return;modal('Taom tannarxi',`<p><strong>${esc(p.name)}</strong></p>`+field('Bir dona tannarxi (so‘m)','cost',Number.isFinite(p.cost)?p.cost:'','number','required min="0" max="100000000" step="1"')+`<p class="metric-note">Masalliq va tayyorlashning bir donaga bevosita xarajati. Ish haqini alohida xarajat sifatida yozsangiz, tannarxga takroran qo‘shmang. 0 — tannarx haqiqatan yo‘q. Eski, qayd etilmagan buyurtmalar taxmin sifatida qayta hisoblanadi.</p>`,'product-cost-form',id);}
function downloadDaily(){const url=URL.createObjectURL(new Blob([dailyText()],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='lazzat-kun-yakuni-'+reportDate+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Kun yakuni hisoboti yuklandi.');}
